def json_dumps(value: Any) -> str:
    import json

    return json.dumps(value, ensure_ascii=False, separators=(",", ":"))


def json_loads(value: str) -> Any:
    import json

    if not value:
        return {}
    try:
        return json.loads(value)
    except (TypeError, ValueError):
        return {}


_MOJI_MARKERS = ("\u00c2", "\u00c3", "\u00e2", "\u0080", "\u009c", "\u0093", "\u0094", "\u009a", "\u009c")


def repair_text(value: str) -> str:
    if not value or not any(ch in value for ch in _MOJI_MARKERS):
        return value
    try:
        repaired = value.encode("latin-1", errors="strict").decode("utf-8")
    except (UnicodeEncodeError, UnicodeDecodeError):
        return value
    if "\ufffd" in repaired:
        return value
    return repaired


def repair_tree(obj: Any) -> Any:
    if isinstance(obj, dict):
        return {key: repair_tree(val) for key, val in obj.items()}
    if isinstance(obj, list):
        return [repair_tree(item) for item in obj]
    if isinstance(obj, str):
        return repair_text(obj)
    return obj


def parse_float(value: Any, default: float = 0) -> float:
    if value is None:
        return default
    if isinstance(value, (int, float)):
        return float(value)
    text = str(value).strip().replace(",", "")
    if not text:
        return default
    try:
        return float(text)
    except ValueError:
        return default


def normalize_text(value: Any) -> str:
    return " ".join(str(value or "").strip().upper().split())


TIRE_REMAINING_WARNING_PERCENT = 35.0
TIRE_REMAINING_CRITICAL_PERCENT = 20.0
TIRE_REMAINING_WARNING_HOURS = 250.0


def normalize_capture_shift_py(value: Any) -> str:
    text = normalize_text(value)
    compact = text.replace(" ", "")
    if compact in {"1", "T1", "TURNO1", "PRIMERO", "DIA"}:
        return "Turno 1"
    if compact in {"2", "T2", "TURNO2", "SEGUNDO", "NOCHE"}:
        return "Turno 2"
    if text == "GENERAL":
        return "General"
    return "Turno 1"


def normalize_part_key(value: Any) -> str:
    text = normalize_text(value)
    return "".join(ch for ch in text if ch.isalnum())


