    canvas.setFillColor(colors.white)
    canvas.setFont("Helvetica-Bold", 9.5)
    canvas.drawCentredString(width - 0.99 * inch, height - 0.365 * inch, "TARJETA")
    canvas.setFont("Helvetica-Bold", 8)
