    canvas.drawRightString(width - doc.rightMargin, height - 0.80 * inch, "Impreso: " + utc_now().strftime("%d/%m/%Y %H:%M:%S"))
    canvas.setStrokeColor(colors.HexColor("#e2e8f0"))
