@app.post("/api/portal/snapshot")
async def publish_portal_snapshot(request: Request, _auth: str | None = Header(default=None, alias="X-MGA-API-Key")) -> dict[str, Any]:
    require_api_key(_auth)
    throttle_sync(request)
    payload = await request.json()
    if not isinstance(payload, dict):
        raise HTTPException(status_code=400, detail="Portal invalido.")
    equipment = payload.get("equipment") or []
    captures = payload.get("captures") or []
    preventives = payload.get("preventives") or []
    availability = payload.get("availability") or []
    if not isinstance(equipment, list) or not isinstance(captures, list) or not isinstance(preventives, list):
        raise HTTPException(status_code=400, detail="El portal debe contener listas validas.")
    payload["ok"] = True
    payload["source"] = "cloud-portal"
    payload["updated_at"] = utc_now().isoformat(timespec="seconds")
    with SessionLocal() as session:
        snapshot = session.scalar(select(PortalSnapshot).where(PortalSnapshot.name == "default"))
        previous_payload: dict[str, Any] = {}
        if snapshot is not None:
            previous_raw = json_loads(snapshot.payload_json)
            if isinstance(previous_raw, dict):
                previous_payload = previous_raw
        if "diesel" not in payload and isinstance(previous_payload.get("diesel"), dict):
            payload["diesel"] = previous_payload["diesel"]
            settings = payload.setdefault("settings", {})
            previous_settings = previous_payload.get("settings") if isinstance(previous_payload.get("settings"), dict) else {}
            if isinstance(settings, dict) and "meta_diesel_lh" not in settings and isinstance(previous_settings, dict):
                settings["meta_diesel_lh"] = previous_settings.get("meta_diesel_lh", 25)
        incoming_history = payload.get("service_history")
        if isinstance(incoming_history, list):
            previous_history = previous_payload.get("service_history") if isinstance(previous_payload.get("service_history"), list) else []
            preserved_history = [
                row for row in previous_history
                if not (isinstance(row, dict) and str(row.get("source") or "").startswith("desktop"))
            ]
            payload["service_history"] = incoming_history + preserved_history
        elif isinstance(previous_payload.get("service_history"), list):
            payload["service_history"] = previous_payload["service_history"]
        incoming_equipment = payload.get("equipment")
        if isinstance(incoming_equipment, list):
            previous_equipment = previous_payload.get("equipment") if isinstance(previous_payload.get("equipment"), list) else []
            prev_by_code = {str(e.get("code") or e.get("equipment_code") or "").strip().upper(): e for e in previous_equipment if isinstance(e, dict)}
            web_fields = ("serial", "brand", "model", "equipment_type", "location", "notes", "photo_data")
            for eq in incoming_equipment:
                if not isinstance(eq, dict):
                    continue
                code = str(eq.get("code") or eq.get("equipment_code") or "").strip().upper()
                prev_eq = prev_by_code.get(code)
                if isinstance(prev_eq, dict):
                    for field in web_fields:
                        val = prev_eq.get(field)
                        if val is not None and val != "":
                            eq[field] = val
        if "preventive_execution" not in payload and isinstance(previous_payload.get("preventive_execution"), dict):
            payload["preventive_execution"] = previous_payload["preventive_execution"]
        if "special_services" not in payload and isinstance(previous_payload.get("special_services"), dict):
            payload["special_services"] = previous_payload["special_services"]
        if "work_orders" not in payload and isinstance(previous_payload.get("work_orders"), dict):
            payload["work_orders"] = previous_payload["work_orders"]
        if "parts_manuals" not in payload and isinstance(previous_payload.get("parts_manuals"), dict):
            payload["parts_manuals"] = previous_payload["parts_manuals"]
        if "audit_log" not in payload and isinstance(previous_payload.get("audit_log"), list):
            payload["audit_log"] = previous_payload["audit_log"]
        if "backlog" not in payload and isinstance(previous_payload.get("backlog"), dict):
            payload["backlog"] = previous_payload["backlog"]
        if "tire_tracking" not in payload and isinstance(previous_payload.get("tire_tracking"), dict):
            payload["tire_tracking"] = previous_payload["tire_tracking"]
        if "kanban" not in payload and isinstance(previous_payload.get("kanban"), dict):
            payload["kanban"] = previous_payload["kanban"]
        payload = merge_mobile_captures_into_portal(session, enrich_tire_tracking(merge_work_orders_into_backlog(merge_preventive_execution_into_portal(payload))))
        payload = repair_tree(payload)
        if snapshot is None:
            snapshot = PortalSnapshot(name="default")
            session.add(snapshot)
        snapshot.updated_at = utc_now()
        snapshot.payload_json = json_dumps(payload)
        session.commit()
    invalidate_read_cache("/api/portal")
    return {
        "ok": True,
        "equipment": len(equipment),
        "captures": len(captures),
        "preventives": len(preventives),
        "service_history": len(payload.get("service_history") or []) if isinstance(payload.get("service_history"), list) else 0,
        "preventive_execution": len((payload.get("preventive_execution") or {}).get("records") or []) if isinstance(payload.get("preventive_execution"), dict) else 0,
        "special_services": len((payload.get("special_services") or {}).get("records") or []) if isinstance(payload.get("special_services"), dict) else 0,
        "work_orders": len((payload.get("work_orders") or {}).get("records") or []) if isinstance(payload.get("work_orders"), dict) else 0,
        "parts_manuals": len((payload.get("parts_manuals") or {}).get("rows") or []) if isinstance(payload.get("parts_manuals"), dict) else 0,
        "audit_log": len(payload.get("audit_log") or []) if isinstance(payload.get("audit_log"), list) else 0,
        "availability": len(availability) if isinstance(availability, list) else 0,
    }


@app.put("/api/equipment/{code}/meta")
async def update_equipment_meta(code: str, request: Request, _auth: str | None = Header(default=None, alias="X-MGA-API-Key")) -> dict[str, Any]:
    require_api_key(_auth)
    code = str(code).strip().upper()
    if not code:
        raise HTTPException(status_code=400, detail="Codigo de equipo requerido.")
    payload = await request.json()
    if not isinstance(payload, dict):
        raise HTTPException(status_code=400, detail="Payload invalido.")
    allowed_fields = {"description", "family", "equipment_type", "brand", "model", "serial", "location", "notes", "photo_data"}
    updates = {k: v for k, v in payload.items() if k in allowed_fields}
    if not updates:
        raise HTTPException(status_code=400, detail="No hay campos validos para actualizar.")
    if "photo_data" in updates:
        photo = str(updates["photo_data"])
        if photo.startswith("data:") and "," in photo:
            header, b64 = photo.split(",", 1)
            try:
                raw = base64.b64decode(b64)
                if len(raw) > 2 * 1024 * 1024:
                    raise HTTPException(status_code=400, detail="La imagen excede 2 MB.")
            except Exception:
                raise HTTPException(status_code=400, detail="Imagen base64 invalida.")
    with SessionLocal() as session:
        snapshot = session.scalar(select(PortalSnapshot).where(PortalSnapshot.name == "default"))
        if snapshot is None:
            raise HTTPException(status_code=404, detail="No hay snapshot del portal.")
        previous_raw = json_loads(snapshot.payload_json)
        if not isinstance(previous_raw, dict):
            raise HTTPException(status_code=500, detail="Snapshot corrupto.")
        equipment = previous_raw.get("equipment") if isinstance(previous_raw.get("equipment"), list) else []
        found = False
        for eq in equipment:
            if isinstance(eq, dict) and str(eq.get("code") or eq.get("equipment_code") or "").strip().upper() == code:
                eq.update(updates)
                found = True
                break
        if not found:
            equipment.append({"code": code, **updates})
            found = True
        previous_raw["equipment"] = equipment
        previous_raw["updated_at"] = utc_now().isoformat(timespec="seconds")
        snapshot.payload_json = json_dumps(previous_raw)
        snapshot.updated_at = utc_now()
        session.commit()
    return {"ok": True, "code": code, "updated": list(updates.keys())}


@app.post("/api/availability/import")
async def import_availability_pdf(request: Request, _auth: str | None = Header(default=None, alias="X-MGA-API-Key")) -> dict[str, Any]:
    require_api_key(_auth)
    payload = await request.json()
    if not isinstance(payload, dict):
        raise HTTPException(status_code=400, detail="Archivo invalido.")
    file_name = str(payload.get("file_name") or "").strip()
    data = str(payload.get("data") or "")
    if not data:
        raise HTTPException(status_code=400, detail="Archivo vacio.")
    if "," in data:
        data = data.split(",", 1)[1]
    try:
        raw = base64.b64decode(data)
    except Exception as exc:
        raise HTTPException(status_code=400, detail="No se pudo decodificar el archivo.") from exc
    if file_name and not file_name.lower().endswith(".pdf"):
        raise HTTPException(status_code=400, detail="Por ahora solo se acepta PDF de disponibilidad.")
    import_date, imported_rows = parse_availability_pdf_rows(raw)
    if not imported_rows:
        raise HTTPException(status_code=400, detail="No se encontraron renglones de disponibilidad en el PDF.")
    with SessionLocal() as session:
        snapshot = session.scalar(select(PortalSnapshot).where(PortalSnapshot.name == "default"))
        if snapshot is None:
            snapshot = PortalSnapshot(name="default")
            session.add(snapshot)
            portal = portal_fallback_payload(session)
        else:
            loaded = json_loads(snapshot.payload_json)
            portal = loaded if isinstance(loaded, dict) else portal_fallback_payload(session)
        current_rows = portal.get("availability") if isinstance(portal.get("availability"), list) else []
        merged, summary = merge_availability_rows(current_rows, imported_rows)
        portal["availability"] = merged
        portal["ok"] = True
        portal["source"] = "cloud-portal"
        portal["updated_at"] = utc_now().isoformat(timespec="seconds")
        snapshot.updated_at = utc_now()
        snapshot.payload_json = json_dumps(portal)
        session.commit()
    with SessionLocal() as session:
        updated_portal = latest_portal_payload(session)
    return {
        "ok": True,
        "file_name": file_name,
        "date": import_date,
        **summary,
        "portal": updated_portal,
    }


def next_tire_event_id(events: list[dict[str, Any]]) -> int:
    current = 0
    for event in events:
        current = max(current, int(parse_float(event.get("id"), 0) or 0))
    return current + 1


